/bin/bash -lc "node -e \"
const withNaming = require('@bem-react/classname').withNaming;
const block = withNaming({ n: 'g-', e: '__', m: '_' });
const b = block('root');
console.log('b() =', b());
console.log('b({theme: true}) =', b({theme: true}));
console.log('modsClassName(b({theme: true})) =', b({theme: true}).split(/\\s(.*)/)[1]);
\""

